<?php
/** Orchard Ledger transport exchange: vehicle capability and service area inform each operational request. */
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';

$vehicleType=normalize_text($_GET['vehicle_type']??'',100);$minCapacity=positive_decimal($_GET['min_capacity']??null);$needsRefrigeration=(int)($_GET['refrigerated']??0)===1;$serviceDistrict=normalize_text($_GET['service_area']??'',100);$conditions=['u.status="active"'];$params=[];if($vehicleType!==''){$conditions[]='EXISTS(SELECT 1 FROM vehicles vf WHERE vf.provider_id=tp.id AND vf.status="available" AND vf.vehicle_type LIKE :vehicle_type)';$params['vehicle_type']='%'.$vehicleType.'%';}if($minCapacity!==null){$conditions[]='EXISTS(SELECT 1 FROM vehicles vc WHERE vc.provider_id=tp.id AND vc.status="available" AND vc.capacity_kg>=:min_capacity)';$params['min_capacity']=$minCapacity;}if($needsRefrigeration)$conditions[]='EXISTS(SELECT 1 FROM vehicles vr WHERE vr.provider_id=tp.id AND vr.status="available" AND vr.is_refrigerated=1)';if($serviceDistrict!==''){$conditions[]='EXISTS(SELECT 1 FROM transport_service_areas tsa JOIN locations la ON la.id=tsa.location_id WHERE tsa.provider_id=tp.id AND la.district=:service_area)';$params['service_area']=$serviceDistrict;}$providers = fetch_all('SELECT tp.*, u.full_name AS contact_name, l.district, GROUP_CONCAT(DISTINCT CONCAT(v.vehicle_type, IF(v.is_refrigerated = 1, " (refrigerated)", "")) ORDER BY v.capacity_kg DESC SEPARATOR ", ") AS fleet, MAX(v.capacity_kg) AS max_capacity, MAX(v.is_refrigerated) AS has_refrigeration FROM transport_providers tp JOIN users u ON u.id=tp.user_id JOIN locations l ON l.id=tp.location_id LEFT JOIN vehicles v ON v.provider_id=tp.id AND v.status="available" WHERE '.implode(' AND ',$conditions).' GROUP BY tp.id ORDER BY max_capacity DESC',$params);$serviceAreas=fetch_all('SELECT DISTINCT l.district FROM transport_service_areas tsa JOIN locations l ON l.id=tsa.location_id ORDER BY l.district');
$farmer = current_user();
$locations = fetch_all('SELECT id, district, tehsil, area FROM locations ORDER BY district, tehsil');
$listings = $farmer !== null && $farmer['role_slug']==='farmer' ? fetch_all('SELECT id,title,quantity_available FROM produce_listings WHERE farmer_id=:farmer AND status="active" ORDER BY title',['farmer'=>$farmer['id']]) : [];
$myRequests = $farmer !== null && $farmer['role_slug']==='farmer' ? fetch_all('SELECT tr.*,COALESCE(tp.company_name,u.full_name) AS provider_name,v.registration_number FROM transport_requests tr LEFT JOIN transport_providers tp ON tp.id=tr.provider_id LEFT JOIN users u ON u.id=tp.user_id LEFT JOIN vehicles v ON v.id=tr.vehicle_id WHERE tr.farmer_id=:farmer ORDER BY tr.created_at DESC LIMIT 20',['farmer'=>$farmer['id']]) : [];
$pageTitle = 'Transport';
require __DIR__ . '/../includes/header.php';
?>
<section class="service-hero"><div class="service-hero-copy"><span class="eyebrow">Transport exchange</span><h1>Match the crop to a capable vehicle.</h1><p>Compare providers by available fleet, practical capacity, refrigerated handling, and service area before you request a pickup.</p></div><div class="service-hero-image transport-hero-local" aria-hidden="true"></div></section>
<section class="section section-paper"><div class="site-container"><form method="get" class="filter-panel transport-filter-grid"><h2>Filter transport providers</h2><div class="form-field"><label>Vehicle type<input name="vehicle_type" value="<?= e($vehicleType) ?>" maxlength="100" placeholder="Truck, pickup, reefer"></label></div><div class="form-field"><label>Minimum capacity (kg)<input name="min_capacity" type="number" min="1" step=".01" value="<?= e((string)($minCapacity??'')) ?>"></label></div><div class="form-field"><label>Service area<select name="service_area"><option value="">All service areas</option><?php foreach($serviceAreas as $area):?><option value="<?= e($area['district']) ?>" <?= $serviceDistrict===$area['district']?'selected':'' ?>><?= e($area['district']) ?></option><?php endforeach;?></select></label></div><label><input type="checkbox" name="refrigerated" value="1" <?= $needsRefrigeration?'checked':'' ?>> Refrigerated vehicle required</label><div class="filter-actions"><button class="button button-primary" type="submit">Apply filters</button><a class="button button-quiet" href="<?= e(app_url('transport/index.php')) ?>">Clear</a></div></form></div></section>
<section class="section"><div class="site-container"><div class="section-heading"><div><span class="eyebrow" style="color:var(--clay)">Available providers</span><h2>Transport terms visible before dispatch.</h2></div><p>Requests progress through acceptance, driver assignment, pickup scheduling, transit, and delivery—each with a recorded status.</p></div><div class="service-grid"><?php if($providers===[]):?><div class="listing-empty"><h2>No active transport providers yet.</h2><p>Transport operators can configure vehicles and service areas from their workspace.</p></div><?php else:foreach($providers as $provider):?><article class="service-card"><span class="badge"><?= (int)$provider['has_refrigeration']===1?'Refrigerated fleet available':'Standard fleet' ?></span><h2><?= e($provider['company_name'] ?: $provider['contact_name']) ?></h2><p><?= e($provider['district']) ?>, Balochistan</p><ul class="service-specs"><li><span>Fleet</span><strong><?= e($provider['fleet'] ?: 'No currently available vehicle') ?></strong></li><li><span>Maximum available capacity</span><strong><?= $provider['max_capacity'] ? number_format((float)$provider['max_capacity'],0).' kg' : 'Not stated' ?></strong></li><li><span>Refrigeration</span><strong><?= (int)$provider['has_refrigeration']===1?'Available':'Not listed' ?></strong></li></ul><?php if($farmer !== null && $farmer['role_slug']==='farmer'):?><a class="button button-primary" href="#request-transport">Request from this provider</a><?php else:?><a class="button button-outline" href="<?= e(app_url('auth/login.php')) ?>">Sign in as farmer to request</a><?php endif;?></article><?php endforeach;endif;?></div></div></section>
<?php if($farmer !== null && $farmer['role_slug']==='farmer'):?><section class="section section-paper" id="request-transport"><div class="site-container booking-layout"><form action="<?= e(app_url('ajax/transport/request.php')) ?>" method="post" class="booking-form" data-ajax-form><span class="eyebrow" style="color:var(--clay)">Transport request</span><h2>Plan a produce pickup</h2><p>Provide the crop, quantity, pickup and delivery details. The selected provider can accept and assign a vehicle or decline the request.</p><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><div class="booking-form-grid"><div class="form-field full"><label for="provider_id">Preferred provider</label><select id="provider_id" name="provider_id" required><option value="">Choose a provider</option><?php foreach($providers as $provider):?><option value="<?= (int)$provider['id'] ?>"><?= e($provider['company_name'] ?: $provider['contact_name']) ?></option><?php endforeach;?></select></div><div class="form-field"><label for="listing_id">Your listing (optional)</label><select id="listing_id" name="listing_id"><option value="">Select later</option><?php foreach($listings as $listing):?><option value="<?= (int)$listing['id'] ?>"><?= e($listing['title']) ?></option><?php endforeach;?></select></div><div class="form-field"><label for="produce_description">Produce description</label><input id="produce_description" name="produce_description" maxlength="160" required></div><div class="form-field"><label for="quantity_kg">Quantity (kg)</label><input id="quantity_kg" name="quantity_kg" type="number" min="1" step="0.01" required></div><div class="form-field"><label for="pickup_date">Pickup date</label><input id="pickup_date" name="pickup_date" type="date" min="<?= date('Y-m-d') ?>" required></div><div class="form-field"><label for="pickup_location_id">Pickup location</label><select id="pickup_location_id" name="pickup_location_id" required><option value="">Choose location</option><?php foreach($locations as $location):?><option value="<?= (int)$location['id'] ?>"><?= e($location['district'].($location['tehsil']?', '.$location['tehsil']:'')) ?></option><?php endforeach;?></select></div><div class="form-field"><label for="delivery_location_id">Delivery location</label><select id="delivery_location_id" name="delivery_location_id" required><option value="">Choose location</option><?php foreach($locations as $location):?><option value="<?= (int)$location['id'] ?>"><?= e($location['district'].($location['tehsil']?', '.$location['tehsil']:'')) ?></option><?php endforeach;?></select></div><div class="form-field"><label for="requires_refrigeration">Temperature handling</label><select id="requires_refrigeration" name="requires_refrigeration"><option value="0">Standard handling</option><option value="1">Refrigerated vehicle needed</option></select></div><div class="full" data-form-feedback></div><button class="button button-primary full" type="submit">Send transport request</button></div></form><aside class="booking-note"><span class="eyebrow">Operational clarity</span><h2>Make the next handover explicit.</h2><p>The provider receives a role-scoped request and can record acceptance, vehicle, driver, pricing, and each movement milestone.</p><ul><li>Providers only see their own incoming requests.</li><li>Farmer-owned listings are verified where one is selected.</li><li>Status changes create a permanent request history.</li></ul></aside></div></section><?php endif;?>
<?php if($farmer !== null && $farmer['role_slug']==='farmer'):?><section class="section"><div class="site-container"><div class="section-heading"><div><h2>Your transport requests</h2><p>Provider quote, assigned vehicle and current delivery milestone.</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Provider</th><th>Load</th><th>Pickup</th><th>Assignment</th><th>Status</th></tr></thead><tbody><?php if($myRequests===[]):?><tr><td colspan="6">No transport requests have been submitted yet.</td></tr><?php else:foreach($myRequests as $request):?><tr><td><?= e($request['reference_code']) ?></td><td><?= e($request['provider_name']??'Provider pending') ?></td><td><?= e($request['produce_description']) ?> · <?= number_format((float)$request['quantity_kg'],0) ?> kg</td><td><?= e(date('j M Y',strtotime($request['pickup_date']))) ?></td><td><?= e($request['registration_number']??'Vehicle pending') ?><br><span class="muted"><?= e($request['driver_name']??'Driver pending') ?><?= $request['estimated_price']?' · Rs. '.number_format((float)$request['estimated_price'],2):'' ?></span></td><td><span class="status-pill <?= e($request['status']) ?>"><?= e(order_status_label($request['status'])) ?></span></td></tr><?php endforeach;endif;?></tbody></table></div></div></section><?php endif;?>
<?php require __DIR__ . '/../includes/footer.php'; ?>

